BEGIN

   BEGIN TRANSACTION;
   WHILE (YEAR(:DATECOUNTER :: TIMESTAMP) = :YEARNUMBER) LOOP
      IF (NOT EXISTS (SELECT 1 FROM
            Dimension.Date
         WHERE
            Date = :DATECOUNTER
      )) THEN
         BEGIN
             INSERT INTO Dimension.Date
                 (Date, "Day Number", Day, Month, "Short Month", "Calendar Month Number", "Calendar Month Label", "Calendar Year", "Calendar Year Label", "Fiscal Month Number", "Fiscal Month Label", "Fiscal Year", "Fiscal Year Label", "ISO Week Number")
             SELECT
               Date,
               "Day Number",
               Day,
               Month,
               "Short Month",
               "Calendar Month Number",
               "Calendar Month Label",
               "Calendar Year",
               "Calendar Year Label",
               "Fiscal Month Number",
               "Fiscal Month Label",
               "Fiscal Year",
               "Fiscal Year Label",
               "ISO Week Number"
             FROM
               TABLE(Integration.GenerateDateDimensionColumns(:DATECOUNTER));
         END;
      END IF;
      DATECOUNTER := DATEADD(day, 1, :DATECOUNTER);
   END LOOP;
   COMMIT;
EXCEPTION
   WHEN OTHER THEN
      IF (CURRENT_TRANSACTION() IS NOT NULL) THEN
         BEGIN
             ROLLBACK;
         EXCEPTION
             WHEN OTHER THEN
               NULL;
         END;
      END IF;
      SYSTEM$LOG_INFO('Unable to populate dates for the year');
      RAISE;
      RETURN COALESCE(TRUNC( -1) :: INT, 0);
END;

IF (CURRENT_TRANSACTION() IS NOT NULL) THEN
   BEGIN
      ROLLBACK;
   EXCEPTION
      WHEN OTHER THEN
         NULL;
   END;
END IF;
